const items = $input.all();
const DOMINIO_PROPRIO = 'ateliersenzapari.com.br';
const resultado = [];

for (const item of items) {
  const json = item.json;
  const nomeCompleto = (json.from && json.from.value && json.from.value[0] && json.from.value[0].name) || '';
  const email = (json.from && json.from.value && json.from.value[0] && json.from.value[0].address) || json.from || '';
  const destinatarios = (json.to && json.to.value) ? json.to.value.map((v) => (v.address || '').toLowerCase()) : [];
  const paraTexto = destinatarios.join(' ');
  const assunto = json.subject || '';
  const mensagem = json.textPlain || json.text || '';

  // Ignora e-mails internos (nossos proprios encaminhamentos/rascunhos) para nao criar lead falso
  if (email.toLowerCase().includes(DOMINIO_PROPRIO)) continue;
  // So processa o que foi endereçado a vendas@
  if (!paraTexto.includes('vendas@')) continue;

  const partesNome = nomeCompleto.trim().split(/\s+/).filter(Boolean);
  const firstname = partesNome[0] || '';
  const lastname = partesNome.slice(1).join(' ');

  resultado.push({
    json: {
      firstname,
      lastname,
      email,
      assunto,
      mensagem,
      data: json.date || new Date().toISOString()
    }
  });
}

return resultado;
